layer.css:
[data-ryt="pitch"] { color: rgb(85, 85, 85); border-left: 4px solid rgb(204, 204, 204); border-radius: 0px; font-family: georgia, times, serif; font-size: 17.5px; font-weight: 400; font-style: normal; line-height: 1.5; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(85, 85, 85); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 0px; padding-right: 0px; padding-bottom: 0px; padding-left: 16px; transition: all; border-top: none; border-right: none; border-bottom: none }
article[data-ryt="rec-card"] { background-color: rgb(255, 255, 255); border-radius: 0px; transition: all }
[data-ryt="footer"] { background-color: var(--ryt-text); font-style: normal; letter-spacing: normal; text-transform: none; color: var(--ryt-bg) }
[data-ryt="credit"] a, [data-ryt="review"] a, [data-ryt="bio"] a { color: var(--ryt-accent); border-radius: 0px; font-weight: 400; font-style: normal; letter-spacing: normal; text-transform: none; text-decoration-line: underline; text-decoration-style: solid; text-decoration-color: var(--ryt-accent); text-decoration-thickness: auto; text-underline-offset: auto; transition: color 0.15s ease-in }
[data-ryt="category"], [data-ryt="tags"] li { color: var(--ryt-accent); border-top: 1px solid var(--ryt-accent); border-right: 1px solid var(--ryt-accent); border-bottom: 1px solid var(--ryt-accent); border-left: 1px solid var(--ryt-accent); border-radius: 9999px; font-family: -apple-system, BlinkMacSystemFont, "avenir next", avenir, "helvetica neue", helvetica, ubuntu, roboto, noto, "segoe ui", arial, sans-serif; font-weight: 400; font-style: normal; line-height: 1.5; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-accent); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 8px; padding-right: 16px; padding-bottom: 8px; padding-left: 16px; transition: color 0.15s ease-in }
[data-ryt="hero"] h1 { font-family: var(--ryt-font-heading); font-size: 48px; font-weight: 200; font-style: normal; line-height: 1.25; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: rgba(255, 255, 255, 0.9); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="section"] > h2 { color: #888888; border-radius: 0px; font-family: var(--ryt-font-heading); font-weight: 200; font-style: normal; line-height: 1.25; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(170, 170, 170); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="review"] { color: rgb(119, 119, 119); font-family: var(--ryt-font-heading); font-size: 16px; font-weight: 400; font-style: normal; line-height: 1.5; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(119, 119, 119); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="credit"], [data-ryt="eyebrow"] { color: rgb(119, 119, 119); font-family: var(--ryt-font-heading); font-size: 14px; font-weight: 400; font-style: normal; line-height: 1.15; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(119, 119, 119); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="brand"] { border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 24px; font-weight: 200; font-style: normal; line-height: 1.15; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: rgba(255, 255, 255, 0.9); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="nav"] a { border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 20px; font-weight: 400; font-style: normal; line-height: 1.15; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: rgba(255, 255, 255, 0.9); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 0px; padding-right: 0px; padding-bottom: 0px; padding-left: 0px; transition: all }
[data-ryt="rec-card"] [data-ryt="title"] a { color: var(--ryt-text); border-radius: 0px; font-family: var(--ryt-font-heading); font-weight: 400; font-style: normal; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; transition: color 0.15s ease-in }
[data-ryt="rec-card"] [data-ryt="title"] { color: var(--ryt-text); border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 16px; font-weight: 400; font-style: normal; line-height: 1.15; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="rec-card"] [data-ryt="title"] a:hover { opacity: 0.5 }
[data-ryt="category"]:hover, [data-ryt="tags"] li:hover { transform: scale(1.05) }
